package com.atlasiq.enterprise;
import jakarta.enterprise.context.ApplicationScoped;import javax.sql.DataSource;import java.nio.charset.StandardCharsets;import java.security.*;import java.sql.*;import java.time.Instant;import java.util.*;
@ApplicationScoped public class AuditLogService {private final DataSource ds;public AuditLogService(DataSource d){ds=d;}public void record(String org,String ws,String actor,String action,String resource){try(Connection c=ds.getConnection()){String prev="";try(PreparedStatement p=c.prepareStatement("SELECT event_hash FROM atlasiq_audit_event WHERE organization_id=? ORDER BY at DESC")){p.setString(1,org);p.setMaxRows(1);try(ResultSet r=p.executeQuery()){if(r.next())prev=r.getString(1);}}Instant at=Instant.now();String id=UUID.randomUUID().toString(),hash=hash(prev+"|"+at+"|"+org+"|"+ws+"|"+actor+"|"+action+"|"+resource);try(PreparedStatement p=c.prepareStatement("INSERT INTO atlasiq_audit_event(id,at,organization_id,workspace_id,actor,action,resource,event_hash,previous_hash) VALUES(?,?,?,?,?,?,?,?,?)")){Object[] v={id,Timestamp.from(at),org,ws,actor,action,resource,hash,prev};for(int i=0;i<v.length;i++)p.setObject(i+1,v[i]);p.executeUpdate();}}catch(Exception e){throw new IllegalStateException(e);}}public List<Event> list(String org,String ws,int limit){List<Event> out=new ArrayList<>();try(Connection c=ds.getConnection();PreparedStatement p=c.prepareStatement("SELECT id,at,actor,action,resource,event_hash,previous_hash FROM atlasiq_audit_event WHERE organization_id=? AND workspace_id=? ORDER BY at DESC")){p.setString(1,org);p.setString(2,ws);p.setMaxRows(Math.min(500,Math.max(1,limit)));try(ResultSet r=p.executeQuery()){while(r.next())out.add(new Event(r.getString(1),r.getTimestamp(2).toInstant(),org,ws,r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7)));}}catch(Exception e){throw new IllegalStateException(e);}return out;}private String hash(String x){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(x.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}public record Event(String id,Instant at,String organizationId,String workspaceId,String actor,String action,String resource,String eventHash,String previousHash){}}
